import {MARASEN_RECORDS} from './marasen-data.js?v=0.87.0';
const QUEST_NAMES={mill:'The Silent Mill',peach:'Liubeirow · the Peach Orchard oath',darius:'The Common Cause · spillway survey'};
export function installSiteTablets(maps){for(const m of Object.values(maps))for(const s of m.spots||[]){const match=s.id?.match(/^mr-(mill|peach|darius)-record-(\d)$/);if(match){s.siteTablet=true;s.questProp=true;s.hintQuest=match[1];s.hintStage=Number(match[2]);s.label='Read the '+(match[1]==='peach'?'oath':match[1]==='mill'?'millwright’s':'spillway')+' tablet';}}}
// A low stone lectern with a weathered bronze face: smaller and lower than the
// tall timber route noticeboard. Its base is the same solid tile used by A.
export function drawSiteTablet(c,s){const x=s.x*16+8,y=s.y*16+14;c.save();c.translate(x,y);c.fillStyle='#122e2866';c.beginPath();c.ellipse(1,0,17,5,0,0,Math.PI*2);c.fill();c.fillStyle='#454c40';c.fillRect(-11,-12,23,12);c.fillStyle='#869180';c.fillRect(-12,-13,23,10);c.fillStyle='#b6bda4';c.fillRect(-12,-13,23,2);c.fillStyle='#4b5447';c.beginPath();c.moveTo(-15,-28);c.lineTo(12,-28);c.lineTo(16,-13);c.lineTo(-13,-13);c.closePath();c.fill();c.fillStyle='#c7c7a7';c.beginPath();c.moveTo(-14,-29);c.lineTo(12,-29);c.lineTo(15,-16);c.lineTo(-12,-16);c.closePath();c.fill();c.fillStyle='#6d795f';c.fillRect(-10,-27,21,10);c.fillStyle='#b8ad78';c.fillRect(-9,-26,19,8);c.fillStyle='#6b654d';for(const [xx,yy]of [[-10,-27],[11,-27],[-8,-17],[12,-17]])c.fillRect(xx,yy,2,2);c.strokeStyle='#3e514a';c.lineWidth=1.4;c.lineCap='round';c.lineJoin='round';
 if(s.hintQuest==='peach'){for(const x of [-5,1,7]){c.beginPath();c.moveTo(x-2,-20);c.lineTo(x-1.5,-23);c.quadraticCurveTo(x,-25,x+1.5,-23);c.lineTo(x+2,-20);c.closePath();c.stroke();c.fillStyle='#3e514a';c.fillRect(x,-19,1,1);}}
 else if(s.hintQuest==='mill'){c.beginPath();c.arc(0,-22,3,0,Math.PI*2);for(let a=0;a<Math.PI*2;a+=Math.PI/3){c.moveTo(Math.cos(a),-22+Math.sin(a));c.lineTo(Math.cos(a)*5,-22+Math.sin(a)*4);}c.stroke();}
 else{c.beginPath();c.moveTo(-5,-25);c.lineTo(-5,-22);c.lineTo(7,-22);for(const x of [-5,1,7]){c.moveTo(x,-22);c.lineTo(x,-19);}c.stroke();}
 c.fillStyle='#cbd3b7';c.fillRect(-10,-9,2,4);c.fillStyle='#627652';c.fillRect(8,-3,5,2);c.restore();}
export function siteTabletHit(s,x,y){return s.siteTablet===true&&x>=s.x-1&&x<=s.x+1&&y>=s.y-1&&y<=s.y;}
// Derive entries from existing discovery flags, so old saves regain their exact
// accounts automatically without unlocking unread records or changing puzzles.
export function siteTabletJournalHTML(state,escape){const groups=Object.entries(QUEST_NAMES).flatMap(([key,name])=>{const read=state.marasen?.quests?.[key]?.records||[];const records=[...new Set(read)].filter(n=>Number.isInteger(n)&&MARASEN_RECORDS[key][n]).sort((a,b)=>a-b);if(!records.length)return[];return '<details><summary>'+escape(name)+' · '+records.length+' recorded '+(records.length===1?'tablet':'tablets')+'</summary>'+records.map(n=>{const [title,...pages]=MARASEN_RECORDS[key][n];return '<article><h4>'+escape(title)+'</h4>'+pages.map(p=>'<p>'+escape(p)+'</p>').join('')+'</article>';}).join('')+'</details>';});return groups.length?'<section class="site-notebook"><h3>Recorded site tablets</h3><p>Exact copies of the accounts you have read. The tablets remain at their sites for another look.</p>'+groups.join('')+'</section>':'';}
